 release=json.loads((SITE/'data/derived/town/release.json').read_text());manifest_path=SITE/'public/town-assets'/release['directory']/'manifest.json'
 if sha(manifest_path)!=release['manifestSha256']:raise ValueError('Source manifest identity changed')
 manifest=json.loads(manifest_path.read_text());owners={}
