 def building_matches(text):
  return[{'id':sid,'sourceOwnerTiles':owners.get(sid,[]),'appearanceCatalogs':catalogs.get(sid,[]),'basis':'Exact stable ID only; source presence is not proof that every appearance detail is implemented.'}for sid in sorted(set(re.findall(r'BLD-(\d{6}_\d{6})',text)))]
 for stem in FILES:
  path=RESEARCH/'sections'/(stem+'.md');lines=path.read_text().splitlines();heading=stem;block=[];start=1
  def flush(end):
   if block:sections.append({'source':stem+'.md','heading':heading,'lineStart':start,'lineEnd':end,'text':'\n'.join(block)})
  for n,line in enumerate(lines,1):
   if line.startswith('#'):
    flush(n-1);heading=line.lstrip('# ').strip();start=n;block=[line];continue
   block.append(line)
   if not line.strip()or re.fullmatch(r'[|\s:\-]+',line)or line.strip().startswith('```'):continue
   status,reason=classify(stem,heading,line)
   if status=='remaining-review':status,reason=close_review(stem,heading,line)
   rows.append({'id':stem+':'+str(n),'source':str(path),'sourceSha256':sha(path),'section':heading,'line':n,'text':line,'status':status,'coverageBasis':reason,'urls':urls(line),'dates':sorted(set(re.findall(r'\b(?:19|20)\d{2}(?:[‑-]\d{2}(?:[‑-]\d{2})?)?\b',line))),'buildingMatches':building_matches(line),'sourceLabels':[label for label in ['Documented','Derived','Inferred','Historical','Unverified','Not established']if label.lower()in line.lower()]})
